import csv
import io
import re

def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    raw_csv = raw_csv.lstrip("\ufeff")
    try:
        csv.field_size_limit(100000000)
    except (OverflowError, csv.Error):
        pass

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )
    records = [list(record) for record in reader]

    expected = [
        "date",
        "time",
        "qty",
        "productid",
        "price",
        "producttype",
        "productdescription",
        "url",
        "comments",
    ]

    def normalize_header(value):
        return re.sub(r"[^a-z0-9]+", "", value.strip().lower().lstrip("\ufeff"))

    header_index = -1
    for index, record in enumerate(records):
        if len(record) == 9:
            normalized = [normalize_header(value) for value in record]
            if normalized == expected:
                header_index = index
                break

    if header_index < 0:
        best_score = -1
        for index, record in enumerate(records):
            if len(record) != 9:
                continue
            normalized = [normalize_header(value) for value in record]
            score = sum(1 for value in normalized if value in expected)
            score += sum(
                2 for position, value in enumerate(normalized)
                if position < len(expected) and value == expected[position]
            )
            if score > best_score:
                best_score = score
                header_index = index

    if header_index < 0:
        return {"columns": [], "rows": []}

    columns = [value.strip().lstrip("\ufeff") for value in records[header_index]]
    width = len(columns)

    date_pattern = re.compile(
        r"^(?:\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}|\d{8})$"
    )
    time_pattern = re.compile(
        r"^\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:\s*[APap][Mm])?$"
    )
    url_pattern = re.compile(r"^(?:https?://|ftp://|www\.)", re.IGNORECASE)

    def is_data_record(record):
        if len(record) < 2:
            return False
        return bool(
            date_pattern.fullmatch(record[0].strip())
            and time_pattern.fullmatch(record[1].strip())
        )

    def repair_width(record):
        if len(record) == width:
            return record

        if len(record) < width:
            return record + [""] * (width - len(record))

        url_index = None
        for index in range(6, len(record)):
            if url_pattern.match(record[index].strip()):
                url_index = index
                break

        if url_index is not None:
            repaired = record[:6]
            repaired.append(",".join(record[6:url_index]))
            repaired.append(record[url_index])
            repaired.append(",".join(record[url_index + 1:]))
            if len(repaired) < width:
                repaired.extend([""] * (width - len(repaired)))
            elif len(repaired) > width:
                repaired = repaired[:width - 1] + [",".join(repaired[width - 1:])]
            return repaired

        return record[:width - 1] + [",".join(record[width - 1:])]

    normalized_header = [normalize_header(value) for value in columns]
    rows = []

    for record in records[header_index + 1:]:
        if not record or all(value == "" for value in record):
            continue
        if len(record) == width:
            candidate = [normalize_header(value) for value in record]
            if candidate == normalized_header:
                continue
        if not is_data_record(record):
            continue
        rows.append([str(value) for value in repair_width(record)])

    return {"columns": columns, "rows": rows}
